  XW += x[8] * 1.2010999999999999e+01;       // C
  XW += x[9] * 1.3018999999999998e+01;       // CH
  XW += x[10] * 1.4026999999999999e+01;      // CH2
  XW += x[11] * 1.4026999999999999e+01;      // CH2(S)
  XW += x[12] * 1.5035000000000000e+01;      // CH3
  XW += x[13] * 1.6042999999999999e+01;      // CH4
  XW += x[14] * 2.8009999999999998e+01;      // CO
  XW += x[15] * 4.4009000000000000e+01;      // CO2
  XW += x[16] * 2.9018000000000001e+01;      // HCO
  XW += x[17] * 3.0026000000000000e+01;      // CH2O
  XW += x[18] * 3.1033999999999999e+01;      // CH2OH
  XW += x[19] * 3.1033999999999999e+01;      // CH3O
  XW += x[20] * 3.2042000000000002e+01;      // CH3OH
  XW += x[21] * 2.5029999999999998e+01;      // C2H
  XW += x[22] * 2.6037999999999997e+01;      // C2H2
  XW += x[23] * 2.7045999999999999e+01;      // C2H3
  XW += x[24] * 2.8053999999999998e+01;      // C2H4
  XW += x[25] * 2.9061999999999998e+01;      // C2H5
  XW += x[26] * 3.0070000000000000e+01;      // C2H6
  XW += x[27] * 4.1028999999999996e+01;      // HCCO
  XW += x[28] * 4.2036999999999999e+01;      // CH2CO
  XW += x[29] * 4.2036999999999999e+01;      // HCCOH
  XW += x[30] * 1.4007000000000000e+01;      // N
  XW += x[31] * 1.5015000000000001e+01;      // NH
  XW += x[32] * 1.6023000000000000e+01;      // NH2
  XW += x[33] * 1.7030999999999999e+01;      // NH3
  XW += x[34] * 2.9021999999999998e+01;      // NNH
  XW += x[35] * 3.0006000000000000e+01;      // NO
  XW += x[36] * 4.6005000000000003e+01;      // NO2
  XW += x[37] * 4.4012999999999998e+01;      // N2O
  XW += x[38] * 3.1014000000000003e+01;      // HNO
  XW += x[39] * 2.6018000000000001e+01;      // CN
  XW += x[40] * 2.7025999999999996e+01;      // HCN
  XW += x[41] * 2.8033999999999999e+01;      // H2CN
  XW += x[42] * 4.1033000000000001e+01;      // HCNN
  XW += x[43] * 4.3024999999999999e+01;      // HCNO
  XW += x[44] * 4.3024999999999999e+01;      // HOCN
  XW += x[45] * 4.3024999999999999e+01;      // HNCO
  XW += x[46] * 4.2017000000000003e+01;      // NCO
  XW += x[47] * 2.8013999999999999e+01;      // N2
  XW += x[48] * 3.9950000000000003e+01;      // AR
  XW += x[49] * 4.3088999999999999e+01;      // C3H7
