  wdot[1] -= 2 * q; // H
  // d()/d[H2]
  dqdci = -k_r * sc[5];
  J[0] += dqdci;      // dwdot[H2]/d[H2]
  J[1] += -2 * dqdci; // dwdot[H]/d[H2]
  // d()/d[H]
