  // reaction 41: 2 H + CO2 <=> H2 + CO2
  // a third-body and non-pressure-fall-off reaction
  // forward
  phi_f = (sc[1] * sc[1]) * sc[15];
  k_f = 550000000 * exp(-2 * logT);
